package de.corporate.lc.company.api;import de.corporate.lc.company.domain.CompanyProfile;import java.time.LocalDateTime;public record CompanyProfileView(Integer id,String legalName,String addressLine,String postalCode,String city,String country,String email,String phone,String taxId,String registrationNumber,String bankName,String iban,String bic,String contactPerson,boolean logoAvailable,String updatedBy,LocalDateTime updatedAt){public static CompanyProfileView from(CompanyProfile p){return new CompanyProfileView(p.getId(),p.getLegalName(),p.getAddressLine(),p.getPostalCode(),p.getCity(),p.getCountry(),p.getEmail(),p.getPhone(),p.getTaxId(),p.getRegistrationNumber(),p.getBankName(),p.getIban(),p.getBic(),p.getContactPerson(),p.getLogo()!=null&&p.getLogo().length>0,p.getUpdatedBy(),p.getUpdatedAt());}}
